const calendarSourceId = $('Loop_Calendars1').item.json.id;
const items = $input.all();

const toNaive = (iso) => {
  if (!iso) return null;
  // Strip timezone: keep wall-clock time as YYYY-MM-DD HH:MM:SS
  return iso.substring(0, 19).replace('T', ' ');
};

// Estados de la app: la cancelación se guarda como 'cancelled' y no existe
// 'tentative' (se toma como pendiente de confirmar).
const mapStatus = (s) => {
  if (s === 'cancelled') return 'cancelled';
  if (s === 'tentative') return 'pending';
  return 'scheduled';
};

const valid = items
  .filter((it) => it.json && it.json.id)
  .map((it) => {
    const ev = it.json;
    const startIso = (ev.start && ev.start.dateTime)
      ? ev.start.dateTime
      : (ev.start && ev.start.date ? ev.start.date + 'T00:00:00' : null);
    const endIso = (ev.end && ev.end.dateTime)
      ? ev.end.dateTime
      : (ev.end && ev.end.date ? ev.end.date + 'T00:00:00' : null);

    return {
      json: {
        calendar_source_id: calendarSourceId,
        google_event_id: ev.id,
        summary: ev.summary || '(Sin título)',
        status: mapStatus(ev.status),
        start_datetime: toNaive(startIso),
        end_datetime: toNaive(endIso),
        color: ev.colorId || null,
        notes: ev.description || null,
      },
    };
  });

// Always emit at least one item so the SplitInBatches loop continues
// even when a calendar has no events. The Insert query filters out
// items with null google_event_id.
if (valid.length === 0) {
  return [{
    json: {
      calendar_source_id: calendarSourceId,
      google_event_id: null,
      summary: null,
      status: null,
      start_datetime: null,
      end_datetime: null,
      color: null,
      notes: null,
    },
  }];
}

return valid;

